`timescale 1ns/1ps
//------------------------------------------------------------------------------
// SPI master device-model testbench
//
// The DUT is a mode-0 (CPOL=0, CPHA=0) MSB-first master that runs entirely in
// pclk: spi_sck is generated by a divider inside the same clock domain, and
// MISO is sampled in SPI_FALL when half_cnt reaches 0 - i.e. on the pclk edge
// where SCK falls.  A device therefore has the whole SCK high phase to drive
// MISO.  This testbench models a slave that changes MISO on the SCK rising edge
// and samples MOSI on the same edge, which is what a real mode-0 slave does.
//
// Covered: known TX/RX patterns, bit order, chip select, final-bit capture,
// STATUS/IRQ, back-to-back transfers, reset during a transfer, disabled
// controller, and the fact that pstrb is ignored (documented limitation).
//------------------------------------------------------------------------------
module tb_spi_device;

  reg         pclk = 0;
  reg         presetn;
  reg         penable, pwrite;
  reg  [31:0] paddr, pwdata;
  reg  [3:0]  pstrb;
  wire [31:0] prdata;
  wire        pready, pslverr;
  wire        spi_sck, spi_mosi, spi_cs_n;
  wire        irq;
  reg         spi_miso;

  always #5 pclk = ~pclk;

  spi_ctrl dut (
    .pclk(pclk), .presetn(presetn), .penable(penable), .pwrite(pwrite),
    .paddr(paddr), .pwdata(pwdata), .pstrb(pstrb), .prdata(prdata),
    .pready(pready), .pslverr(pslverr), .spi_sck(spi_sck), .spi_mosi(spi_mosi),
    .spi_miso(spi_miso), .spi_cs_n(spi_cs_n), .irq(irq)
  );

  integer errors = 0;

  //--------------------------------------------------------------------------
  // Slave device model: MSB first, changes MISO on the rising edge, samples
  // MOSI on the rising edge (CPHA=0 data is valid before the first edge).
  //--------------------------------------------------------------------------
  reg [7:0] dev_tx, dev_shift, dev_rx;
  integer   dev_bits;

  // MOSI is sampled on the rising edge (master drives it on the falling edge).
  always @(posedge spi_sck) if (!spi_cs_n) begin
    dev_rx   = {dev_rx[6:0], spi_mosi};
    dev_bits = dev_bits + 1;
  end

  // MISO changes on the falling edge so it is stable well before the master
  // samples it, and holds for the whole high phase (mode 0).
  always @(negedge spi_sck) if (!spi_cs_n) begin
    dev_shift = {dev_shift[6:0], 1'b0};
    spi_miso  = dev_shift[7];
  end

  //--------------------------------------------------------------------------
  // APB helpers: one setup cycle + one access cycle.
  //--------------------------------------------------------------------------
  task apb_write(input [31:0] a, input [31:0] d);
    begin
      @(negedge pclk);
      paddr = a; pwdata = d; pwrite = 1; pstrb = 4'hF; penable = 0;
      @(negedge pclk);
      penable = 1;
      @(negedge pclk);
      penable = 0; pwrite = 0;
      if (!pready) begin
        $display("[spi] FAIL pready low during write to %h", a);
        errors = errors + 1;
      end
    end
  endtask

  task apb_read(input [31:0] a, output [31:0] d);
    begin
      @(negedge pclk);
      paddr = a; pwrite = 0; pstrb = 4'hF; penable = 0;
      @(negedge pclk);
      penable = 1;
      @(negedge pclk);
      d = prdata;
      penable = 0;
    end
  endtask

  reg [31:0] rd;
  integer    n;
  integer    cs_asserted, cs_released;

  // Watch chip select while a transfer runs.
  always @(spi_cs_n) begin
    if (!spi_cs_n) cs_asserted = cs_asserted + 1;
    else           cs_released = cs_released + 1;
  end

  task run_transfer(input [7:0] tx, input [7:0] rx, input [255:0] name);
    begin
      dev_tx    = rx;
      dev_shift = rx;
      dev_rx    = 8'd0;
      dev_bits  = 0;
      // CPHA=0: the first bit must already be valid before SCK's first edge.
      spi_miso  = rx[7];

      apb_write(32'h04, {24'd0, tx});
      apb_write(32'h08, 32'h1);

      n = 0;
      while (!(irq) && n < 400) begin
        @(negedge pclk);
        n = n + 1;
      end

      apb_read(32'h04, rd);
      if (rd[7:0] !== rx) begin
        $display("[spi] FAIL %0s: master received %h expected %h", name, rd[7:0], rx);
        errors = errors + 1;
      end else begin
        $display("[spi] pass %0s: master received %h", name, rd[7:0]);
      end

      if (dev_rx !== tx) begin
        $display("[spi] FAIL %0s: slave received %h expected %h", name, dev_rx, tx);
        errors = errors + 1;
      end else begin
        $display("[spi] pass %0s: slave received %h", name, dev_rx);
      end

      apb_read(32'h0C, rd);
      if (rd[1:0] !== 2'b10) begin
        $display("[spi] FAIL %0s: STATUS busy/done = %b expected 10", name, rd[1:0]);
        errors = errors + 1;
      end
    end
  endtask

  initial begin
    $dumpfile("build/sim/tb_spi_device.vcd");
    $dumpvars(0, tb_spi_device);

    presetn = 0; penable = 0; pwrite = 0; paddr = 0; pwdata = 0; pstrb = 0;
    spi_miso = 1'b0;
    dev_tx = 0; dev_shift = 0; dev_rx = 0; dev_bits = 0;
    cs_asserted = 0; cs_released = 0;
    repeat (4) @(posedge pclk);
    presetn = 1;
    repeat (2) @(posedge pclk);

    // T1 — reset values
    apb_read(32'h00, rd);
    if (rd !== 32'd0) begin
      $display("[spi] FAIL T1 CTRL reset value %h expected 0", rd);
      errors = errors + 1;
    end
    apb_read(32'h10, rd);
    if (rd[15:0] !== 16'd8) begin
      $display("[spi] FAIL T1 CLKDIV reset value %0d expected 8", rd[15:0]);
      errors = errors + 1;
    end
    if (spi_cs_n !== 1'b1 || spi_sck !== 1'b0) begin
      $display("[spi] FAIL T1 idle pins cs_n=%b sck=%b", spi_cs_n, spi_sck);
      errors = errors + 1;
    end else begin
      $display("[spi] pass T1 reset values and idle pins");
    end

    // T2 — start is ignored while the controller is disabled
    dev_shift = 8'h5A; dev_bits = 0;
    apb_write(32'h08, 32'h1);
    repeat (20) @(negedge pclk);
    apb_read(32'h0C, rd);
    if (rd[1:0] !== 2'b00 || cs_asserted != 0) begin
      $display("[spi] FAIL T2 disabled start: status=%b cs_asserted=%0d", rd[1:0], cs_asserted);
      errors = errors + 1;
    end else begin
      $display("[spi] pass T2 start ignored while disabled");
    end

    // Enable with a short divider so the test stays fast.
    apb_write(32'h00, 32'h1);
    apb_write(32'h10, 32'd3);

    // T3/T4 — known patterns in both directions
    run_transfer(8'hA5, 8'h3C, "T3 A5 <- 3C");
    run_transfer(8'h00, 8'hFF, "T4 00 <- FF");
    run_transfer(8'hFF, 8'h00, "T5 FF <- 00");
    run_transfer(8'h5A, 8'h5A, "T6 5A <- 5A");

    // T7 — chip select is released after each transfer
    if (cs_asserted < 4 || cs_released < 4) begin
      $display("[spi] FAIL T7 cs toggling: asserted=%0d released=%0d",
               cs_asserted, cs_released);
      errors = errors + 1;
    end else begin
      $display("[spi] pass T7 chip select asserted/released per transfer");
    end

    // T8 — pstrb is not honoured (documented limitation): a partial write with
    // pstrb=0 still updates the register because the RTL ignores pstrb.
    @(negedge pclk);
    paddr = 32'h10; pwdata = 32'd5; pwrite = 1; pstrb = 4'b0000; penable = 0;
    @(negedge pclk); penable = 1;
    @(negedge pclk); penable = 0; pwrite = 0;
    apb_read(32'h10, rd);
    if (rd[15:0] !== 16'd5) begin
      $display("[spi] note: pstrb is honoured now (CLKDIV=%0d) - update the docs", rd[15:0]);
    end else begin
      $display("[spi] pass T8 pstrb ignored, as documented");
    end

    // T9 — reset during a transfer
    dev_shift = 8'hFF; dev_bits = 0;
    apb_write(32'h04, 32'hAA);
    apb_write(32'h08, 32'h1);
    repeat (12) @(negedge pclk);
    if (spi_cs_n !== 1'b0) begin
      $display("[spi] FAIL T9 transfer did not start (cs_n high)");
      errors = errors + 1;
    end
    presetn = 0;
    repeat (3) @(posedge pclk);
    if (spi_cs_n !== 1'b1 || spi_sck !== 1'b0 || dut.busy !== 1'b0 || dut.done !== 1'b0) begin
      $display("[spi] FAIL T9 reset mid-transfer: cs_n=%b sck=%b busy=%b done=%b",
               spi_cs_n, spi_sck, dut.busy, dut.done);
      errors = errors + 1;
    end else begin
      $display("[spi] pass T9 reset during transfer clears the controller");
    end
    presetn = 1;
    repeat (4) @(posedge pclk);

    // T10 — the controller works again after the reset
    apb_write(32'h00, 32'h1);
    apb_write(32'h10, 32'd3);
    run_transfer(8'hC3, 8'h96, "T10 after reset");

    if (errors == 0) begin
      $display("SPI DEVICE: ALL TESTS PASSED");
    end else begin
      $display("SPI DEVICE: %0d FAILURES", errors);
      $fatal;
    end
    $finish;
  end

  initial begin
    #2000000;
    $display("SPI DEVICE: TIMEOUT");
    $fatal;
  end

endmodule
